      _sessionExpired = false;
      notifyListeners();
      return _jwt;
    } on Object catch (e) {
      _jwt = null;
      if (_terminalRefreshFailure(e)) _refreshRejectedAccount = account;
      _sessionExpired = true;
      AppLog.i('fa_network', 'account refresh FAILED: $e');
      notifyListeners();
      return null;
    }
  }

