    final client = _newClient();
    AppLog.i(
      'fa_network',
      'join $networkId (jwt=${_jwt != null}, displayName=${displayName ?? "-"})',
    );
    final result = await client.joinNetwork(
      networkId,
      password: [REDACTED:Sensitive-Value],
      displayName: displayName,
